{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-4wADwA/src/cycle.js","content":"/**
 * Finds a cycle in the dependency graph, if one exists, using a depth-first
 * search that starts from each task in ascending name order and walks each
 * task's dependencies in ascending name order. Returns the first cycle found
 * as an array of names running from the re-entered task, through the search
 * stack, back to that task; returns `null` when the graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const state = new Map()
  const stack = []

  function sortedDeps(name) {
    const set = deps.get(name)
    return set ? [...set].sort() : []
  }

  function dfs(node) {
    state.set(node, 1)
    stack.push(node)
    for (const dep of sortedDeps(node)) {
      const depState = state.get(dep)
      if (depState === 1) {
        const idx = stack.indexOf(dep)
        return stack.slice(idx).concat(dep)
      }
      if (depState !== 2) {
        const found = dfs(dep)
        if (found) return found
      }
    }
    state.set(node, 2)
    stack.pop()
    return null
  }

  for (const name of [...tasks.keys()].sort()) {
    if (!state.has(name)) {
      const found = dfs(name)
      if (found) return found
    }
  }
  return null
}
"}

