{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-4wADwA/src/schedule.js","content":"/**
 * Computes, for every task, the unlimited-worker start/finish time and the
 * wave (depth) it sits in. A task's start is the greatest finish among its
 * dependencies (0 when it has none); its depth is one more than the greatest
 * depth among its dependencies (0 when it has none).
 */
export function computeTimings(tasks, deps) {
  const timings = new Map()

  function sortedDeps(name) {
    const set = deps.get(name)
    return set ? [...set].sort() : []
  }

  function resolve(name) {
    const cached = timings.get(name)
    if (cached) return cached

    const depNames = sortedDeps(name)
    let start = 0
    let depth = 0
    for (const depName of depNames) {
      const depTiming = resolve(depName)
      if (depTiming.finish > start) start = depTiming.finish
      if (depTiming.depth + 1 > depth) depth = depTiming.depth + 1
    }
    const cost = tasks.get(name)
    const timing = { start, finish: start + cost, depth }
    timings.set(name, timing)
    return timing
  }

  for (const name of tasks.keys()) resolve(name)
  return timings
}

/** Groups task names into waves (ascending depth), each sorted by name. */
export function computeWaves(tasks, timings) {
  const byDepth = []
  for (const name of tasks.keys()) {
    const depth = timings.get(name).depth
    if (!byDepth[depth]) byDepth[depth] = []
    byDepth[depth].push(name)
  }
  for (const wave of byDepth) {
    if (wave) wave.sort()
  }
  return byDepth
}

/** The makespan with unlimited workers: the greatest finish time, or 0. */
export function computeTotal(timings) {
  let total = 0
  for (const timing of timings.values()) {
    if (timing.finish > total) total = timing.finish
  }
  return total
}
"}

