import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parseGraph.js'
import { findCycle } from './cycle.js'
import { computeTimings, computeWaves, computeTotal } from './schedule.js'
import { packSchedule } from './pack.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: Number.parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE, 2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function runWaves(tasks, deps) {
  const timings = computeTimings(tasks, deps)
  const waves = computeWaves(tasks, timings)
  const lines = []
  for (let depth = 0; depth < waves.length; depth++) {
    const wave = waves[depth]
    if (wave) lines.push(`wave ${depth}: ${wave.join(' ')}`)
  }
  lines.push(`total ${computeTotal(timings)}`)
  return lines.join('\n') + '\n'
}

function runExplain(tasks, deps) {
  const timings = computeTimings(tasks, deps)
  const names = [...tasks.keys()].sort()
  const lines = names.map((name) => {
    const { start, finish, depth } = timings.get(name)
    return `${name} start=${start} finish=${finish} depth=${depth}`
  })
  lines.push(`total ${computeTotal(timings)}`)
  return lines.join('\n') + '\n'
}

function runPack(tasks, deps, workers) {
  const { workerRuns, makespan } = packSchedule(tasks, deps, workers)
  const lines = workerRuns.map((runs, i) => {
    const tasksPart = runs.map((run) => ` ${run.name}@${run.start}-${run.finish}`).join('')
    return `worker ${i}:${tasksPart}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const args = parseArgs(process.argv.slice(2))
  const input = readStdin()
  const { tasks, deps } = parseGraph(input)

  const cycle = findCycle(tasks, deps)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exit(3)
  }

  let output
  if (args.mode === 'waves') output = runWaves(tasks, deps)
  else if (args.mode === 'explain') output = runExplain(tasks, deps)
  else output = runPack(tasks, deps, args.workers)

  process.stdout.write(output)
}

